public class SkillState : State<Player>
{
	public static string staticID = string.Empty;

	public string skillID = "UnnamedSkill";

	public StatData skillData;

	public ElementType element;

	public bool isUnlocked;

	public bool hasSignatureVariant;

	public bool signatureUnlocked;

	public bool isSignature;

	public int currentLevel;

	public bool isUltimate;

	public BoolVarStat empoweredStat;

	public bool isBasic;

	public bool isDash;

	public bool isMovementSkill;

	public bool isJumpSkill;

	public bool isMeleeSkill;

	public bool isProjectileSkill;

	public bool isBuffSkill;

	public bool isSummonSkill;

	public static int MaxSkillFlags = 8;

	public float currentAnimTime;

	public float animStartTime;

	public float animHoldTime;

	public float animExecTime;

	public float cancelThreshold = 1f;

	public float runThreshold = 1f;

	public float exitThreshold = 1f;

	public Vector2 inputVector;

	public int skillSlot = -1;

	public bool isChargeSkill;

	public bool applyStopElementStatus;

	public bool disableStartCooldown;

	public bool startCooldownOnEnter = true;

	public Cooldown cooldownRef;

	public bool useSmartCD;

	public bool cdStarted;

	public bool allowSelfTransition;

	public bool allowRepeating;

	public bool repeatLock;

	public bool isHoldSkill;

	public bool holdStarted;

	public bool holdReleased;

	public bool updateHoldAnim = true;

	public bool skillExecuted;

	public SkillState prevSkillState;

	private SkillState cancelToDashSkill;

	public virtual bool IsEmpowered => empoweredStat.CurrentValue;

	public virtual string OnEnterAnimStr => parent.NextHandAnimStr;

	public virtual string OnHoldAnimStr => parent.LastHandAnimStr;

	public SkillState(string newName, FSM newFSM, Player newEnt)
		: base(newName, newFSM, newEnt)
	{
		InitializeSkill();
		skillID = newName;
		SetSkillData();
		RegisterSkill();
	}

	public void InitializeSkill()
	{
		currentLevel = 0;
		isUltimate = false;
		isUnlocked = false;
		signatureUnlocked = false;
		empoweredStat = new BoolVarStat(newBaseVal: false);
	}

	public void SetSkillData()
	{
		skillData = StatManager.GetSkillData(parent.skillCategory, skillID);
		if (skillData == null)
		{
			Debug.Log("No skillData found in StatManager for skillID: " + skillID + " in category: " + parent.skillCategory);
			return;
		}
		element = (ElementType)Enum.Parse(typeof(ElementType), skillData.GetValue<string>("elementType"));
		if (!elementSkillDict[element].Contains(skillID))
		{
			elementSkillDict[element].Add(skillID);
		}
	}

	public void RegisterSkill()
	{
		parent.skillsDict[skillID] = this;
		parent.cooldownManager.Add(skillID, skillData.GetValue<float>("cooldown", currentLevel), skillData, this);
		cooldownRef = parent.cooldownManager.cooldowns[skillID];
	}

	public virtual void SetAnimTimes(float newStart = 0f, float newHold = 0.2f, float newExecute = 0.3f, float newCancel = 0.6f, float newRun = 0.8f, float newExit = 1f)
	{
		animStartTime = newStart;
		animHoldTime = newHold;
		animExecTime = newExecute;
		cancelThreshold = newCancel;
		runThreshold = newRun;
		exitThreshold = newExit;
	}

	public void InitChargeSkillSettings(int maxCharges, float delayBetweenCharges, StatData statData, SkillState skillState)
	{
		isChargeSkill = true;
		cooldownRef.isChargeSkill = true;
		cooldownRef.chargeCount = maxCharges;
		cooldownRef.MaxChargeCount = maxCharges;
		cooldownRef.chargeDelayTime = delayBetweenCharges;
		cooldownRef.statData = statData;
		cooldownRef.skillState = skillState;

public class ProjectileAttackState : SkillState
{
	private Projectile newProjectile;

	public ProjectileAttackState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		isProjectileSkill = true;
	}

	public GameObject GetPrefabResource(string str)
	{
		return ChaosBundle.Get("Assets/Prefabs/Projectiles/" + str + ".prefab");
	}

	public virtual Projectile CreateProjectile(GameObject prefab, Vector3? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTrans = null, bool setAtkInfo = true)
	{
		newProjectile = Projectile.CreateProjectile(parent, prefab, (Vector2)((!givenPosition.HasValue) ? parent.attackOriginTrans.position : givenPosition.Value), (!givenQuaternion.HasValue) ? Quaternion.identity : givenQuaternion.Value, parentTrans ?? parent.transform.parent);
		if (setAtkInfo)
		{
			SetProjectileAtkInfo(newProjectile);
		}
		return newProjectile;
	}

	public virtual void FireProjectile(Projectile projectile, Vector2 moveVector, bool setKnockbackVector = true, float newMoveSpeed = 0f, float newFlyTime = 0f, string audioString = "", bool setAtkInfo = false)
	{
		projectile.transform.SetParent(null);
		if (setAtkInfo)
		{
			SetProjectileAtkInfo(projectile);
		}
		projectile.moveVector = moveVector;
		if (setKnockbackVector)
		{
			projectile.attackBox.knockbackOverwriteVector = moveVector;
		}
		if (newMoveSpeed != 0f)
		{
			projectile.moveSpeed = newMoveSpeed;
		}
		if (newFlyTime != 0f)
		{
			projectile.flyTime = newFlyTime;
			projectile.lifeTime = newFlyTime * 2f;
		}
		projectile.RefreshFlightTime();
		if (audioString != string.Empty)
		{
			SoundManager.PlayWithDistAndSPR(audioString, projectile.transform.position);
		}
	}

	public virtual void SetProjectileAtkInfo(Projectile projectile)
	{
		projectile.attackBox.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
		projectile.UpdateCalculatedDamage(initDamageOverride: true);
	}
}

public class ProjectileChainAttackState : ProjectileAttackState
{
	public float shotDelay = 0.125f;

	public int shotStopwatchID;

	public bool attackStarted;

	public bool firstAnim;

	public bool updateInput = true;

	private Vector2 checkAimVec;

	public ProjectileChainAttackState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		disableStartCooldown = true;
		isHoldSkill = true;
		InitChargeSkillSettings(skillData.GetValue<int>(StatData.spawnStr), 0f, skillData, this);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		UpdateCDCounter();
		attackStarted = false;
		firstAnim = true;
	}

	public override void HandleHoldButton()
	{
		if (!StartAttack())
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
		{
		case StopwatchState.Ready:
			if (firstAnim)
			{
				firstAnim = false;
				AnnounceSkillExecuteEvent();
			}
			else if (updateInput)
			{
				checkAimVec = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
				if (checkAimVec != Vector2.zero)
				{
					inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
				}
				parent.anim.PlayDirectional(OnHoldAnimStr, -1, animExecTime);
			}
			if (cooldownRef.chargeCount > 0)
			{
				cooldownRef.chargeCount--;
			}
			if (!cooldownRef.IsCharging)
			{
				UpdateCDCounter();
			}
			FireChainProjectile();
			break;
		case StopwatchState.Done:
			skillExecuted = true;
			break;
		}
		CancelToDash();
	}

	public override void OnExit()
	{
		base.OnExit();
		StartCooldownTimer(-1f, expendCharge: false);
		ChaosStopwatch.Stop(shotStopwatchID);
	}

	public virtual void UpdateCDCounter()
	{
		StartCooldownTimer(-1f, expendCharge: false);
		ChaosStopwatch.Pause(cooldownRef.remainingTimeStopwatchID);
	}

	public virtual bool StartAttack()
	{
		if (!attackStarted)
		{
			if (!parent.anim.AnimPlayed(animExecTime))
			{
				return false;
			}
			attackStarted = true;
			shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotDelay, cooldownRef.chargeCount);
		}
		return true;
	}

	public virtual void FireChainProjectile()
	{
	}
}

public class ProjectileChargeAttackState(string newName, FSM newFSM, Player newPlayer) : ProjectileHoldAttackState(newName, newFSM, newPlayer)
{
	public bool useCastBar = true;

public class ProjectileChargeAttackState(string newName, FSM newFSM, Player newPlayer) : ProjectileHoldAttackState(newName, newFSM, newPlayer)
{
	public bool useCastBar = true;

	public int maxCharge = 10;

	public int minCharge = 5;

	public float chargeTime = 0.2f;

	public float calcChargeTime;

	public int chargeStopwatchID;

	public bool fullyCharged;

	public int postStopwatchID;

	public AudioSource chargeAudioSource;

	public string chargeAudioID = string.Empty;

	public bool ignoreAudioIsPlaying;

	public bool lowerChargeTimeOnEmpower = true;

	public override void OnEnter()
	{
		base.OnEnter();
		calcChargeTime = ((!lowerChargeTimeOnEmpower || !IsEmpowered) ? chargeTime : (chargeTime * 0.5f));
		fullyCharged = maxCharge - minCharge <= 0;
		if (useCastBar && !fullyCharged)
		{
			parent.hud.castBar.StartCast(ChaosStopwatch.Begin(calcChargeTime * (float)(maxCharge - minCharge)), givenStatus: true);
		}
		PlayChargeEffects();
	}

	public override void HandleHoldButton()
	{
		base.HandleHoldButton();
		if (!fullyCharged)
		{
			switch (ChaosStopwatch.CheckInterval(chargeStopwatchID))
			{
			case StopwatchState.Ready:
				PlayChargeEffects();
				AddProjectileCharge();
				break;
			case StopwatchState.Done:
				fullyCharged = true;
				postStopwatchID = ChaosStopwatch.Begin(calcChargeTime);
				break;
			}
		}
		else
		{
			HandlePostStopwatch();
		}
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		if (useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
		StopChargeAudio();
	}

	public override void OnExit()
	{
		base.OnExit();
		if (useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
		StopChargeAudio();
	}

	public override Projectile CreateHoldProjectile()
	{
		chargeStopwatchID = ChaosStopwatch.Begin(calcChargeTime, useInterval: true, calcChargeTime, maxCharge - minCharge);
		return base.CreateHoldProjectile();
	}

	public virtual void HandlePostStopwatch()
	{
		if (ChaosStopwatch.Check(postStopwatchID))
		{
			postStopwatchID = ChaosStopwatch.Begin(calcChargeTime);
			PlayChargeEffects();
		}
	}

	public virtual void PlayChargeEffects()
	{
		if (!(chargeAudioID == string.Empty))
		{
			if (ignoreAudioIsPlaying)
			{
				StopChargeAudio();
			}
			if (currentProjectile != null)
			{
				chargeAudioSource = SoundManager.PlayIfNotPlaying(chargeAudioID, chargeAudioSource, currentProjectile.transform);
			}
		}
	}

	public void StopChargeAudio()
	{
		if (chargeAudioSource != null)
		{
			chargeAudioSource.Stop();
		}
	}

	public virtual void AddProjectileCharge()
	{
	}
}

public class ProjectileHoldAttackState : ProjectileAttackState
{
	public GameObject projectilePrefab;

	public Projectile currentProjectile;

	public float holdRange = 1f;

	public string fireAudioID = string.Empty;

	public bool updateRotation;

	public bool recenterOnRelease = true;

	public override string OnEnterAnimStr => parent.ChargeAnimStr;

	public override string OnHoldAnimStr => parent.ChargeAnimStr;

	public virtual Vector2 HoldPosition => (Vector2)parent.attackOriginTrans.position - Entity.GetFacingDirectionVector(parent.facingDirection) * holdRange;

	public ProjectileHoldAttackState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		disableStartCooldown = true;
		isHoldSkill = true;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		CreateHoldProjectile();
	}

	public override void Update()
	{
		if (currentProjectile == null)
		{
			ExitToSkillOrRunOrIdle();
		}
		else
		{
			base.Update();
		}
	}

	public override void HandleHoldButton()
	{
		base.HandleHoldButton();
		if (!(currentProjectile == null))
		{
			currentProjectile.RefreshFlightTime();
			currentProjectile.transform.position = HoldPosition;
			if (updateRotation)
			{
				currentProjectile.transform.localEulerAngles = Globals.GetRotationVector(inputVector);
			}
		}
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		StartCooldownTimer();
		parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
		if (!(currentProjectile == null))
		{
			if (updateRotation)
			{
				currentProjectile.isPointedAtMoveVector = false;
			}
			if (recenterOnRelease)
			{
				currentProjectile.transform.position = parent.attackOriginTrans.position;
			}
			Projectile projectile = currentProjectile;
			Vector2 moveVector = inputVector;
			string audioString = fireAudioID;
			FireProjectile(projectile, moveVector, setKnockbackVector: true, 0f, 0f, audioString);
		}
	}

	public override void OnExit()
	{
		if (!skillExecuted && currentProjectile != null)
		{
			currentProjectile.ResetProjectile();
			StartCooldownTimer();
		}
		base.OnExit();
	}

	public virtual Projectile CreateHoldProjectile()
	{
		return currentProjectile = CreateProjectile(projectilePrefab, HoldPosition, (!updateRotation) ? Quaternion.identity : Globals.GetRotationQuaternion(inputVector));
	}
}

public class PunchBasic : MeleeAttackState
{
	public new static string staticID = "PunchBasic";

	public PunchBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		setParent = true;
		attackPrefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/PunchBasic.prefab");
		alwaysStartForehand = true;
		maxComboCount = 5;
		animStartTime = 0.25f;
		animExecTime = 0.3f;
		baseCancelThreshold = 0.45f;
		finalCancelThreshold = 0.55f;
		baseExitThreshold = 0.75f;
		forceMovement = true;
		attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 2f, 10, VarStatModType.OverrideWithMods);
		finalAttackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 50f, 10, VarStatModType.OverrideWithMods);
		animNames = new string[5] { "Punch", "Punch", "Punch", "Punch", "PunchFinal" };
	}

	public override void GetAttackAndMoveVectors(int attackCount)
	{
		base.GetAttackAndMoveVectors(attackCount);
		if (attackCount == maxComboCount)
		{
			parent.movement.EndMovement();
		}
	}

	public override void ExecuteAttack()
	{
		base.ExecuteAttack();
		if (comboCounter == maxComboCount)
		{
			parent.movement.MoveToMoveVector();
			PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, movementVector);
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.movement.EndMovement();
	}
}

public class ShockTouchBasic : MeleeAttackState
{
	public new static string staticID = "ShockTouchBasic";

	private ShockTouchObject shockTouchObj;

	private Vector2 attackPos;

	public ShockTouchBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		isMeleeSkill = true;
		attackPrefab = ShockTouchObject.Prefab;
		destroyAttackObjectOnExit = false;
		setParent = false;
		maxComboCount = 4;
		animStartTime = 0.25f;
		animExecTime = 0.3f;
		baseCancelThreshold = 0.4f;
		finalCancelThreshold = 0.6f;
		baseRunThreshold = 0.8f;
		finalRunThreshold = 0.9f;
		baseExitThreshold = 1f;
		cooldownRef.skillState = skillState;
		cooldownRef.remainingTimeStopwatchID = -1;
		cooldownRef.delayStopwatchID = -1;
	}

	public virtual void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		empoweredStat.Modify(givenMod, givenStatus);
		if (parent.skillEmpowerEventHandlers != null)
		{
			parent.skillEmpowerEventHandlers(this);
		}
	}

	public virtual bool IsReady()
	{
		if ((isMovementSkill && !parent.MovementEnabled) || (isUltimate && !IsOverdriveReady()) || (!isUltimate && !cooldownRef.Ready))
		{
			return false;
		}
		if (allowSelfTransition && !allowRepeating && repeatLock)
		{
			return false;
		}
		return true;
	}

	public virtual bool IsOverdriveReady()
	{
		return true;
	}

	public bool Transition()
	{
		if (!IsReady() || (!allowSelfTransition && fsm.currentStateName == skillID))
		{
			return false;
		}
		fsm.ChangeState(skillID, allowSelfTransition: true);
		return true;
	}

	public int SetSkillSlot()
	{
		for (int i = 0; i < parent.assignedSkills.Length; i++)
		{
			if (parent.assignedSkills[i] != null && parent.assignedSkills[i].skillID == skillID)
			{
				skillSlot = i;
				return skillSlot;
			}
		}
		skillSlot = -1;
		return skillSlot;
	}

	public void SetRepeatLock(bool setLock = true)
	{
		repeatLock = setLock;
	}

	public void UpdateRepeatLock(string buttonName = "")
	{
		if (skillSlot != -1)
		{
			if (buttonName == string.Empty)
			{
				buttonName = "Skill" + skillSlot;
			}
			if (parent.inputDevice.GetButtonUp(buttonName))
			{
				SetRepeatLock(setLock: false);
			}
		}
	}

	public virtual void StartCooldownTimer(float overrideValue = -1f, bool expendCharge = true)
	{
		if (useSmartCD)
		{
			if (cdStarted)
			{
				return;
			}
			cdStarted = true;
		}
		if ((skillData.GetValue<float>("cooldown") == 0f && overrideValue == -1f) || parent == null || parent.gameObject == null || !parent.gameObject.activeSelf)
		{
			return;
		}
		if (isChargeSkill)
		{
			if (expendCharge && cooldownRef.chargeCount > 0)
			{
				cooldownRef.chargeCount = Mathf.Max(0, cooldownRef.chargeCount - ((!(overrideValue > 0f)) ? 1 : ((int)overrideValue)));
			}
			parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
		}
		else
		{
			parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
		}
	}

	public void ApplyStopElement()
	{
		if (parent.dotManager != null)
		{
			parent.dotManager.ApplyStopElement(element);
		}
	}

	public void BaseOnEnter()
	{
		SetRepeatLock();
		SetSkillSlot();
		if (parent.skillEnterEventHandlers != null)
		{
			parent.skillEnterEventHandlers(this);
		}
		if (fsm.previousState is SkillState)
		{
			prevSkillState = fsm.previousState as SkillState;
			if (isBasic)
			{
				if (!prevSkillState.isBasic && parent.cancelToBasicEventHandlers != null)
				{
					parent.cancelToBasicEventHandlers(this, prevSkillState);
				}
			}
			else if (prevSkillState.isBasic && parent.cancelFromBasicEventHandlers != null)
			{
				parent.cancelFromBasicEventHandlers(this, prevSkillState);
			}
			else if (isDash && parent.cancelToDashEventHandlers != null)
			{
				parent.cancelToDashEventHandlers(this, prevSkillState);
			}
		}
		cdStarted = false;
		if (!disableStartCooldown && startCooldownOnEnter)
		{
			StartCooldownTimer();
		}
