		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 15;
		float z = Globals.GetRotationVector(-inputVector).z;
		Vector3? emitPosition = parent.transform.position + (Vector3)inputVector * 0.5f;
		poolItem.EmitDirBurst(particleCount, z, 12f, -1f, 0.4f, emitPosition);
		SoundManager.PlayWithDistAndSPR("VacuumShot", spawnPosition);
