				{
					hitList.RemoveAt(num);
				}
				else
				{
					tempEnt.rigidbody2D.velocity = dragVector;
				}
			}
			StopwatchState stopwatchState = ChaosStopwatch.CheckInterval(burstStopwatchID);
			if (stopwatchState == StopwatchState.Ready && moveVector != Vector2.zero)
			{
				intervalCount++;
				PoolManager.GetPoolItem<ParticleEffect>("WindSwirlMed").Emit(1, transform.position, localEulerAngles: Globals.GetRotationVector(moveVector), overrides: WindSwirlMedOverride);
				if (intervalCount > 2 && !isEmpowered)
