					Vector2 startPos = transform.position - (Vector3)moveVector * 2f;
					Vector2 endPos = transform.position - (Vector3)moveVector;
					float startLifetime = trailLifeTime;
					Vector3? boxThickness = Vector3.right;
					Color32? startColor = trailColor;
					poolItem.Emit(startPos, endPos, -1, emitEveryOther: true, -1f, snapToFit: true, startLifetime, 0f, startColor, useEndEmitter: true, boxThickness);
