		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(GrabTargetOnContact));
	}

	public override void HandleWallCollision(Collider2D other)
	{
		if (hitWall)
		{
			return;
		}
		hitWall = true;
		projectileSpriteRenderer.enabled = false;
		if (hitList.Count > 0)
		{
			PoolManager.GetPoolItem<ParticleEffect>("WindBurstEffect").Emit(8, transform.position);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 80;
			float scale = 0.25f;
			Vector3? emitPosition = transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		}
		else
		{
			ParticleEffect poolItem2 = PoolManager.GetPoolItem<ParticleEffect>("WindWallHitEffect");
			int? particleCount2 = 1;
			Vector3? emitPosition = transform.position;
			Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
			poolItem2.Emit(particleCount2, emitPosition, null, localEulerAngles);
		}
		AttackInfo attackInfo = attackBox.GenerateAttackInfo(attackBox.statData, wallHitAtkLevel, attackBox.atkInfo.isUltimate);
		attackInfo.knockbackVector = moveVector * attackInfo.knockbackMultiplier;
		moveVector = Vector2.zero;
		for (int num = hitList.Count - 1; num >= 0; num--)
		{
			if (hitList[num] != null)
