			{
				ResetProjectile();
			}
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!isEmpowered || !empoweredEffectStarted || empoweredEffectFinished)
		{
			if (useArc)
			{
				arcLerpValue = arcStopwatch.TimePercentage;
