				moveVector = (initMoveVector + lerpExtVector).normalized;
			}
			else if (boomerangReturning && parentTrans != null)
			{
				moveVector = (parentTrans.position - transform.position).normalized;
			}
			attackBox.knockbackOverwriteVector = moveVector;
		}
	}

	private void InitArcVars()
	{
