	{
		base.Awake();
		atkCollider = attackBox.GetComponent<CircleCollider2D>();
	}

	public override void Start()
	{
		atkStopwatch.SetDelay(atkInterval);
		if (isEmpowered)
		{
			baseMoveSpeed = moveSpeed * 0.75f;
			finalMoveSpeed = 0f;
			moveStopwatch.SetDelay(empStopTime, stopCurrent: false, autoStart: true);
			atkCollider.radius = 2.25f;
			mainMod = startPartSys.main;
			mainMod.startSize = 6f;
			mainMod = frontPartSys.main;
			mainMod.startSize = 5f;
			mainMod = backPartSys.main;
			mainMod.startSize = 5f;
		}
		else
		{
			baseMoveSpeed = moveSpeed;
			finalMoveSpeed = moveSpeed * finalSpeedMultiplier;
			moveStopwatch.IsRunning = true;
		}
		startPartSys.Emit(15);
		base.Start();
		string audioID = "WindArrowEnd";
		Vector2? soundOrigin = transform.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		SetAudioStatus(givenStatus: true);
