			moveSpeed = Mathf.Lerp(baseMoveSpeed, finalMoveSpeed, moveLerpValue);
			moveSlowed = moveLerpValue >= 1f;
			if (moveSlowed)
			{
				startPartSys.Emit(15);
			}
		}
	}

