			frontPartSys.Stop();
			backPartSys.Stop();
			SetAudioStatus(givenStatus: false);
		}
		if (!resetStopwatch.IsRunning)
		{
			base.ResetProjectile();
		}
	}

	public override void HandleWallCollision(Collider2D other)
	{
