		{
			ResetProjectile();
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (!(givenEnt == null) && !(givenEnt is Destructible))
		{
			if (hitCount == 0)
			{
				moveSlowed = false;
				baseMoveSpeed = moveSpeed;
				finalMoveSpeed = 0f;
				moveStopwatch.SetDelay(0.25f, stopCurrent: true, autoStart: true);
				moveVector = (givenEnt.hurtBoxTransform.position - transform.position).normalized;
				flyTime = (float)atkCount * atkStopwatch.Delay * 1.25f;
				RefreshFlightTime();
			}
			hitCount++;
			if (hitCount >= atkCount)
			{
				ResetProjectile();
			}
		}
	}

	private void SetAudioStatus(bool givenStatus)
	{
		if (givenStatus)
		{
			twistAudio = SoundManager.PlayIfNotPlaying("TornadoLoop", twistAudio, transform, useStdPitchOverride: false, 1.2f, 0.05f);
			return;
		}
		if (twistAudio != null && twistAudio.isPlaying)
		{
			twistAudio.Stop();
		}
		SoundManager.PlayAudioWithDistance("WindCircle", transform.position, null, 24f, 0.5f, 1.2f);
	}
}

