	private IEnumerator EmitShockwave(int waveNo, Vector3 moveVec)
	{
		yield return waitForDelay;
		if (gameObject.activeSelf && !(wavePoolTrans[waveNo] == null) && wavePoolTrans[waveNo].gameObject.activeSelf)
		{
