using System;
using UnityEngine;

public class WindFalcon : Projectile
{
	private static GameObject prefab;

	private static GameObject lockOnPrefab;

	public Entity targetEntity;

	private float diveSpeed = 36f;

	private float diveRadius = 6f;

	private float diveMaxDistSq = 150f;

	private float diveMinDistSq = 0.5f;

	private float diveReposDistSq = 5f;

	private Vector2 diveTargetPos = Vector2.zero;

	private Vector2 diveInitPos = Vector2.zero;

	private float distToTarget;

	private float distToInit;

	private int distIndex;

	public int maxHits = 7;

	private int hitCount;

	private bool repositioning;

	private bool targetHit;

	private Vector2 currentPosition;

	private Vector2 targetPosition;

	private GameObject lockOnMarker;

	private bool useDelayedSpeedUp;

	[HideInInspector]
	public bool isUltimate;

	[HideInInspector]
	public bool skipInitialAirBurst;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/WindFalcon.prefab"));

	public static GameObject LockOnPrefab => lockOnPrefab ?? (lockOnPrefab = ChaosBundle.Get("Assets/Prefabs/UI/LockOnMarker.prefab"));

	public override void Start()
	{
		base.Start();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		attackBox.knockbackOverwriteVector = moveVector;
		PoolManager.GetPoolItem<DashAirBurst>().Burst(transform.position, moveVector);
		anim.Play((!isUltimate) ? "Idle" : "IdleLarge", -1, 0f);
		string audioID = "WindChirp";
		Transform originTrans = transform;
		SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		if (isUltimate)
		{
			SoundManager.PlayAudioWithDistance("WindBlastDeep", transform.position);
		}
		else
		{
			SoundManager.PlayAudioWithDistance("WindBlastSharp", transform.position);
		}
	}

	public override void Update()
	{
		base.Update();
		if (repositioning)
		{
			Reposition();
		}
		else if (targetHit)
		{
			Dive();
		}
	}

	public override void UpdateCalculatedDamage(bool initDamageOverride = false)
	{
		base.UpdateCalculatedDamage(initDamageOverride);
		calculatedDamage *= maxHits;
		if (attackBox.atkInfo.isUltimate)
		{
			calculatedDamage *= 5;
		}
	}

	private void UpdatePositionVars()
	{
		currentPosition = transform.position;
		distToInit = Vector2.SqrMagnitude(currentPosition - diveInitPos);
		distToTarget = Vector2.SqrMagnitude(currentPosition - diveTargetPos);
	}

	private void Dive()
	{
		UpdatePositionVars();
		if (distToInit > diveMaxDistSq || distToTarget < diveMinDistSq)
		{
			if (targetEntity != null)
			{
				targetPosition = targetEntity.hurtBoxTransform.position;
			}
			distIndex = ((!Globals.RandBool) ? UnityEngine.Random.Range(5, 8) : UnityEngine.Random.Range(1, 4));
			diveTargetPos = targetPosition + Globals.GetRotatedCircleVector(8, distIndex, currentPosition - targetPosition);
			diveInitPos = currentPosition;
			moveVector = (diveTargetPos - currentPosition).normalized;
			attackBox.knockbackOverwriteVector = moveVector;
			repositioning = true;
			isPointedAtMoveVector = false;
			RefreshFlightTime();
			anim.Play("Idle", -1, 0f);
			hitCount++;
			if (hitCount >= maxHits)
			{
				ResetProjectile();
			}
		}
	}

	private void Reposition()
	{
		UpdatePositionVars();
		if (distToInit > diveReposDistSq || distToTarget < diveMinDistSq)
		{
			if (targetEntity != null)
			{
				targetPosition = targetEntity.hurtBoxTransform.position;
			}
			moveVector = (targetPosition - currentPosition).normalized;
			attackBox.knockbackOverwriteVector = moveVector;
			diveTargetPos = targetPosition + moveVector * diveRadius;
			diveInitPos = currentPosition;
			repositioning = false;
			isPointedAtMoveVector = false;
			RefreshFlightTime();
			anim.Play("Attack", -1, 0f);
			PoolManager.GetPoolItem<DashAirBurst>().Burst(transform.position, moveVector);
			if (useDelayedSpeedUp)
			{
				useDelayedSpeedUp = false;
				moveSpeed = diveSpeed;
			}
		}
	}

	public override void HandleWallCollision(Collider2D other)
	{
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("WindWallHitEffect");
		int? particleCount = 1;
		Vector3? position = transform.position;
		Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
		poolItem.Emit(particleCount, position, null, localEulerAngles);
		moveVector = -moveVector;
		OnTargetHit(null);
		base.HandleWallCollision(other);
	}

	public override void ResetProjectile()
	{
		ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("WindWallHitEffect");
		int? particleCount = 1;
		Vector3? position = transform.position + (Vector3)moveVector;
		Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
		poolItem.Emit(particleCount, position, null, localEulerAngles);
		base.ResetProjectile();
	}

	public void SetLockOnParams(Entity givenEntity, bool delaySpeed = false)
	{
		if (!targetHit && !(givenEntity == null))
		{
			targetHit = true;
			targetEntity = givenEntity;
			goThroughWalls = true;
			RefreshFlightTime();
			anim.Play("Idle", -1, 0f);
			if (delaySpeed)
			{
				useDelayedSpeedUp = true;
			}
			else
			{
				moveSpeed = diveSpeed;
			}
			currentPosition = transform.position;
			diveTargetPos = currentPosition + moveVector * diveRadius;
			diveInitPos = currentPosition - moveVector * diveRadius;
			lockOnMarker = UnityEngine.Object.Instantiate(LockOnPrefab, targetEntity.hurtBoxTransform.position, Quaternion.identity, targetEntity.hurtBoxTransform);
		}
	}

	private void OnDestroy()
	{
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		if (lockOnMarker != null)
		{
			UnityEngine.Object.Destroy(lockOnMarker);
		}
	}

	private void OnTargetHit(Entity givenEntity)
	{
		if (isUltimate)
		{
			isUltimate = false;
			Vector2 vector = transform.position;
			PoolManager.GetPoolItem<ParticleEffect>("WindBurstEffect").Emit(3, vector + moveVector * 0.25f);
			for (int i = -2; i <= 2; i++)
			{
				Vector2 rotatedCircleVector = Globals.GetRotatedCircleVector(12, i, moveVector);
				WindFalcon windFalcon = (WindFalcon)Projectile.CreateProjectile(parentEntity, Prefab, vector + rotatedCircleVector, Globals.GetRotationQuaternion(rotatedCircleVector));
				windFalcon.attackBox.SetAttackInfo(attackBox.atkInfo);
				windFalcon.moveVector = rotatedCircleVector;
				windFalcon.maxHits = maxHits;
				windFalcon.moveSpeed = 20f;
				windFalcon.SetLockOnParams(givenEntity, delaySpeed: true);
				windFalcon.skipInitialAirBurst = true;
			}
		}
		else if (!targetHit)
		{
			SetLockOnParams(givenEntity);
		}
		else if (givenEntity != null && givenEntity == targetEntity && hitCount >= maxHits - 1)
		{
			ResetProjectile();
		}
	}
}

