	}
	if (isEnemy)
	{
		health.ignoreHurtVarStat.RemoveMod(Health.baseIgnoreMod);
		health.healthStat.AddMod(EnemyGlobalStatManager.healthMod);
		movement.moveSpeedStat.AddMod(new NumVarStatMod("EnemyMinion", -0.3f, 10, VarStatModType.Multiplicative));
		if (spriteRenderer != null)
		{
			spriteRenderer.material.SetColor("_OutlineColor", outlineColor);
