public virtual bool HandleTeleportToPlayer(Vector2 givenPosition, bool forceMove = false)
{
	if (forceMove || Vector2.Distance(transform.position, givenPosition) > teleportToPlayerRange)
	{
		PlaySpawnEffect(transform.position);
		transform.position = givenPosition;
		Vector2 startPos = givenPosition;
		Vector2 vec = givenPosition;
		float radius = teleportDiff;
		givenPosition = Globals.GetLinecastVector(startPos, vec.Randomize(1f, radius), ChaosCollisions.layerAllWallAndObst);
		rigidbody2D.MovePosition(givenPosition);
		PlaySpawnEffect(givenPosition);
		return true;
	}
	return false;
}

