	private Vector2 spawnPosition;

	private Vector2 atkVector;

	private bool skillReady = true;

	public override string OnEnterAnimStr => parent.PBAoEAnimStr;

	public UseVortexOrbital(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		disableStartCooldown = true;
		SetAnimTimes(0f, 0.2f, 0.1f, 0.5f, 0.7f);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		spawnCount = ((!IsEmpowered) ? 4 : 5);
	}

	public override bool IsReady()
	{
		return skillReady && base.IsReady();
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		spawnPosition = parent.transform.position;
		atkVector = (Globals.GetPerpendicular(inputVector, horizontal: false) + inputVector).normalized;
		for (int i = 0; i < 5; i++)
		{
			if (voArray[i] != null)
			{
				voArray[i].Stop();
			}
			if (i < spawnCount)
			{
				voArray[i] = CreateVortexOrbital(spawnPosition, Globals.GetRotatedCircleVector(spawnCount, i, atkVector));
			}
		}
		SoundManager.PlayWithDistAndSPR("WindBlastSharp", spawnPosition);
		CameraController.ShakeCamera(0.3f);
		parent.StartCoroutine(HandleCooldown());
	}

	public override void OnExit()
	{
		base.OnExit();
		if (!skillExecuted)
		{
			StartCooldownTimer();
		}
	}

	private VortexOrbital CreateVortexOrbital(Vector2 givenPos, Vector2 givenVec)
	{
		currentVO = ChaosInst<VortexOrbital>(VortexOrbital.Prefab, givenPos + givenVec);
		currentVO.attack.SetAttackInfo(parent.skillCategory, skillID);
		currentVO.orbitTrans = parent.transform;
		currentVO.orbitInitVec = givenVec;
		return currentVO;
	}

	private IEnumerator HandleCooldown()
	{
		skillReady = false;
		int iter = 0;
		while (!skillReady)
		{
			for (iter = 0; iter < 5 && (!(voArray[iter] != null) || !voArray[iter].useOrbit); iter++)
			{
				skillReady = true;
				StartCooldownTimer();
			}
			yield return Globals.waitFor0p15;
		}
	}
}

public class UseSonicBoom : ProjectileAttackState
{
	public new static string staticID = "UseSonicBoom";

	private int atkStopwatchID;

	private bool atkStarted;

	private bool firstSpawn;

	private Vector2 spawnPosition;

	private Vector2 perpendVec;

	private Projectile currentSB;

	private List<Projectile> sbList = new List<Projectile>();

	private bool resetOnHit = true;

	private bool isTracking;

	private string skillStr;

	private int itr;

	public UseSonicBoom(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		startCooldownOnEnter = false;
		SetAnimTimes(0.18f, 0.2f, 0.3f, 0.5f, 0.6f);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		resetOnHit = !IsEmpowered;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		atkStarted = false;
		firstSpawn = true;
		isTracking = true;
		sbList.Clear();
		skillStr = "Skill" + SetSkillSlot();
	}

	public override void ExecuteSkill()
	{
		if (!atkStarted)
		{
			atkStarted = true;
			atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.05f, 12);
			parent.overheadPrompt.DisplayPrompt("Slot" + skillSlot);
			CameraController.ShakeCamera(0.25f);
		}
		switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
		{
		case StopwatchState.Ready:
			parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
			spawnPosition = (Vector2)parent.attackOriginTrans.position + inputVector * 0.6f;
			CreateSonicBoom(spawnPosition);
			if (isUltimate)
			{
				perpendVec = Globals.GetPerpendicular(inputVector);
				CreateSonicBoom(spawnPosition + perpendVec);
				CreateSonicBoom(spawnPosition - perpendVec);
			}
			else if (firstSpawn)
			{
				firstSpawn = false;
				CreateSonicBurst(spawnPosition);
			}
			break;
		case StopwatchState.Done:
			base.ExecuteSkill();
			parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animExecTime);
			break;
		}
		HandleTracking();
	}

	public override void ConcludeSkill()
	{
		if (isTracking)
		{
			isTracking = parent.inputDevice.GetButton(skillStr);
			HandleTracking();
		}
		else
		{
			base.ConcludeSkill();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		sbList.Clear();
		parent.overheadPrompt.HidePrompt(string.Empty);
	}

	private void CreateSonicBurst(Vector2 givenPos)
	{
		for (int i = 0; i < 4; i++)
		{
			CreateSonicBoom(givenPos);
		}
	}

	private void CreateSonicBoom(Vector2 givenPos)
	{
		currentSB = CreateProjectile(SonicBoom.Prefab, givenPos + UnityEngine.Random.insideUnitCircle);
		currentSB.disableOnHit = resetOnHit;
		FireProjectile(currentSB, inputVector, setKnockbackVector: true, 10f, 3f, "GaleBoomerang");
		sbList.Add(currentSB);
		SoundManager.PlayAudioWithDistance("WindArrowStart", parent.transform.position, null, 24f, -1f, 1.1f);
		PoolManager.GetPoolItem<ParticleEffect>("WindTwirlSmallEffect").Emit(1, currentSB.transform.position, ParticleEffectOverrides.StartColorAlpha0p25);
	}

	private void HandleTracking()
	{
		if (!isTracking)
		{
			return;
		}
		CancelToDash();
		inputVector = parent.GetInputVector(!skillExecuted);
		isTracking = false;
		for (itr = sbList.Count - 1; itr > -1; itr--)
		{
			if (!(sbList[itr] == null))
			{
				sbList[itr].moveVector = (sbList[itr].moveVector + inputVector * 0.2f).normalized;
				isTracking = true;
			}
		}
	}
}

public class UseAeroRipple : ProjectileAttackState
{
	public new static string staticID = "UseAeroRipple";

	private static float flyRange = 3.5f;

	private static float[] scaleArr = new float[5] { 1f, 0.875f, 0.75f, 0.625f, 0.5f };

	private static float[] speedArr = new float[5] { 16f, 14f, 12f, 10f, 8f };

	private static float[] timeArr;

	private int rippleCount = 3;

	private Vector2 spawnPosition;

	private AeroRipple currentAR;

	private Vector2 ultVector;

	private int ultStopwatchID;

	private bool ultStarted;

	private bool ultBlasted;

	public UseAeroRipple(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		allowSelfTransition = true;
		allowRepeating = true;
		SetAnimTimes(0.15f, 0.2f, 0.25f, 0.5f, 0.7f);
		InitChargeSkillSettings(2, 0f, skillData, this);
		if (timeArr == null)
		{
			timeArr = new float[speedArr.Length];
			for (int i = 0; i < speedArr.Length; i++)
			{
				timeArr[i] = flyRange / speedArr[i];
			}
		}
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		rippleCount = ((!IsEmpowered) ? 3 : 4);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.movement.EndMovement();
		CameraController.ShakeCamera(0.125f);
		if (isUltimate)
		{
			StartCooldownTimer(99f);
			allowSelfTransition = false;
			allowRepeating = false;
			ultStarted = false;
			ultBlasted = false;
		}
		else
		{
			allowSelfTransition = true;
			allowRepeating = true;
			SetSkillLevel(1);
		}
	}

	public override void ExecuteSkill()
	{
		if (isUltimate)
		{
			if (!ultStarted)
			{
				ultStarted = true;
				ultStopwatchID = ChaosStopwatch.Begin(0.25f, useInterval: true, 0.25f, 2);
				CreateRippleCircle(2, 4f, givenOffset: false, givenOut: false);
				return;
			}
			switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
			{
			case StopwatchState.Ready:
				if (!ultBlasted)
				{
					ultBlasted = true;
					CreateRippleCircle(3, 0f, givenOffset: true, givenOut: true);
					parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
					CameraController.ShakeCamera(0.2f);
				}
				else
				{
					CreateRippleCircle(2, 1.5f, givenOffset: false, givenOut: true);
					parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animExecTime);
					CameraController.ShakeCamera(0.3f);
				}
				break;
			case StopwatchState.Done:
				base.ExecuteSkill();
				break;
			}
			CancelToDash();
		}
		else
		{
			base.ExecuteSkill();
			spawnPosition = parent.attackOriginTrans.position;
			CreateRipples(spawnPosition + inputVector * flyRange, -inputVector, rippleCount);
			PlayAudio(spawnPosition, useBlast: false);
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.ToggleEnemyFloorCollisions();
	}

	private void CreateRippleCircle(int givenLevel, float givenRange, bool givenOffset, bool givenOut)
	{
		SetSkillLevel(givenLevel);
		spawnPosition = parent.attackOriginTrans.position;
		for (int i = (givenOffset ? 1 : 0); i < 12; i += 2)
		{
			ultVector = Globals.GetRotatedCircleVector(12, i, inputVector);
			CreateRipples(spawnPosition + ultVector * givenRange, (!givenOut) ? (-ultVector) : ultVector, 3);
		}
		PlayAudio(spawnPosition);
	}

	private void CreateRipples(Vector2 givenPosition, Vector2 givenVector, int givenCount)
	{
		PoolManager.GetPoolItem<ParticleEffect>("AirVortex").Emit(2, givenPosition);
		for (int i = 0; i < givenCount; i++)
		{
			CreateAeroRipple(givenPosition, givenVector, i);
		}
	}

	private void CreateAeroRipple(Vector2 givenPosition, Vector2 givenVector, int givenIndex)
	{
		currentAR = (AeroRipple)CreateProjectile(AeroRipple.Prefab, givenPosition - givenVector * 0.2f * givenIndex, Globals.GetRotationQuaternion(givenVector));
		currentAR.transform.localScale = new Vector3(scaleArr[givenIndex], 1f, 1f);
		AeroRipple projectile = currentAR;
		float newMoveSpeed = speedArr[givenIndex];
		FireProjectile(projectile, givenVector, setKnockbackVector: true, newMoveSpeed, timeArr[givenIndex], string.Empty);
	}

	private void PlayAudio(Vector2 givenPosition, bool useBlast = true)
	{
		SoundManager.PlayWithDistAndSPR("AirJet", givenPosition);
		SoundManager.PlayWithDistAndSPR((!useBlast) ? "WindBlastSharp" : "WindBlastDeep", givenPosition);
	}
}

