	private int lifeStopwatchID;

	private int primeStopwatchID;

	private bool primed;

	private bool detonated;

	private Vector2 blastPos;

	private Vector2 atkVec;

	private Vector3 atkRoteVec;

	private string skillCat;

	private string skillID;

	private bool skillEmp;

	private Entity parentEnt;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/AirSlideTrap.prefab");
			}
			return _prefab;
		}
	}

	public void Initialize(string givenCat, string givenID, Vector2 givenVec, bool givenEmp, Entity givenEnt)
	{
		skillCat = givenCat;
		skillID = givenID;
		parentEnt = givenEnt;
		attack.SetAttackInfo(skillCat, skillID, 3);
		atkVec = givenVec;
		atkRoteVec = Globals.GetRotationVector(atkVec);
		trapSprite.transform.localEulerAngles = atkRoteVec;
		skillEmp = givenEmp;
		if (skillEmp)
		{
			lifeTime = 4f;
			primeTime = 0.3f;
			blastRadius = 1.75f;
		}
		WindBurst.CreateBurst(transform.position + Vector3.up * 0.9f, string.Empty, string.Empty);
	}

	private void Start()
	{
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		primeStopwatchID = ChaosStopwatch.Begin(primeTime);
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(Detonate));
		Attack attack2 = this.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(Detonate));
		atkCollider.radius = blastRadius;
		circleSprite.transform.localScale = new Vector3(blastRadius * 0.25f, blastRadius * 0.25f, 1f);
		SoundManager.PlayWithDistAndSPR("WindArrowStart", transform.position);
	}

	private void Update()
	{
		if (detonated)
		{
			return;
		}
		if (ChaosStopwatch.Check(lifeStopwatchID))
		{
			Detonate();
			return;
		}
		if (!primed)
		{
			if (!ChaosStopwatch.Check(primeStopwatchID))
			{
				return;
			}
			primed = true;
			anim.Play("Idle", -1, 0f);
			atkCollider.enabled = true;
		}
		HandleAudio();
	}

	private void Detonate(Entity givenEnt = null)
	{
		if (!detonated)
		{
			detonated = true;
			anim.Play("Detonate", -1, 0f);
			Attack attack = this.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(Detonate));
			blastPos = transform.position;
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 20;
			float scale = 0.25f;
			Vector3? emitPosition = blastPos;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			blastPos += Vector2.up * 0.9f;
			if (givenEnt != null)
			{
				CreateVacuumShot();
			}
			PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave").Emit(1, blastPos, localEulerAngles: atkRoteVec, overrides: ParticleEffectOverrides.StartColorAlpha0p25);
			PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave").Emit(1, blastPos + atkVec, localEulerAngles: atkRoteVec, overrides: ParticleEffectOverrides.StartColorAlpha0p25);
			HandleAudio(status: false);
			SoundManager.PlayWithDistAndSPR("WindArrowStart", blastPos);
			if (gameObject != null)
			{
				UnityEngine.Object.Destroy(gameObject, 0.25f);
			}
		}
	}

	private void HandleAudio(bool status = true)
	{
		if (status)
		{
			if (windAudio == null || ChaosStopwatch.Check(audioStopwatchID))
			{
				audioStopwatchID = ChaosStopwatch.Begin(0.25f);
				windAudio = SoundManager.PlayWithDistAndSPR("WindCircle", transform.position);
			}
		}
		else if (windAudio != null)
		{
			windAudio.Stop();
			windAudio = null;
		}
	}

	private void CreateVacuumShot()
	{
		VacuumShot vacuumShot = (VacuumShot)Projectile.CreateProjectile(parentEnt, VacuumShot.Prefab, blastPos, Globals.GetRotationQuaternion(atkVec));
		vacuumShot.attackBox.SetAttackInfo(skillCat, skillID);
		vacuumShot.moveVector = atkVec;
		vacuumShot.transform.localScale *= ((!skillEmp) ? 1.25f : 1.75f);
		SoundManager.PlayWithDistAndSPR("VacuumShot", transform.position);
	}
}

public class BaseDashState : SkillState
{
	public bool showEffects = true;

	public bool playSFX = true;

	public bool cooldownReady;

	public bool prevCDWasReady;

	public bool finishedDashing;

	public float dashDuration = 0.125f;

	public NumVarStatMod dashDurationMod;

	public BoolVarStat forceEvadeStat;

	public NumVarStatMod evadeMod;

	public BoolVarStatMod airborneMod;

	public BaseDashState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isDash = true;
		isMovementSkill = true;
		forceEvadeStat = new BoolVarStat(newBaseVal: false);
		evadeMod = new NumVarStatMod("DashEvade", 1f, 10, VarStatModType.Override);
		airborneMod = new BoolVarStatMod(SkillState.staticID, newModValue: true);
		dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
	}

	public override bool IsReady()
	{
		return parent.MovementEnabled && (!allowSelfTransition || allowRepeating || !repeatLock) && (!isUltimate || IsOverdriveReady());
	}

	public override void OnEnter()
	{
		if (parent.dashSlideIgnored)
		{
			cooldownReady = prevCDWasReady;
			disableStartCooldown = true;
		}
		else
		{
			cooldownReady = cooldownRef.Ready;
			prevCDWasReady = cooldownReady;
			disableStartCooldown = !cooldownReady;
		}
		parent.dashSlideIgnored = false;
		BaseOnEnter();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.AddMod(evadeMod);
		}
		finishedDashing = false;
		dashDurationMod.modValue = dashDuration;
		parent.movement.dashDurationStat.AddMod(dashDurationMod);
		parent.movement.dashTimer = dashDuration;
		if (parent.inputDevice == null)
		{
			inputVector = Vector2.zero;
		}
		else if (parent.inputDevice.IsMouseDash)
		{
			inputVector = GetInputVector();
		}
		else
		{
			inputVector = GetInputVector(faceInputVector: true, (parent.inputDevice.inputScheme == ChaosInputDevice.InputScheme.Gamepad && ChaosInputDevice.lockControllerAim) ? true : false);
		}
		parent.movement.dashVector = inputVector;
		parent.anim.PlayDirectional(parent.DashAnimStr);
		if (showEffects && !cooldownReady)
		{
			PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, inputVector);
			parent.dustEmitter.EmitDirBurst(15, Globals.GetRotationVector(-inputVector).z);
			parent.dashTrails.SetActive(value: true);
		}
		if (playSFX)
		{
			SoundManager.PlayWithDistAndSPR("StandardDash", parent.transform.position);
		}
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.airborneStat.AddMod(airborneMod);
		AnnounceSkillExecuteEvent();
	}

	public override void Update()
	{
		if (finishedDashing)
		{
			ExitTransition();
		}
	}

	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			finishedDashing = parent.movement.DashToTarget();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
		DashFinished();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.RemoveMod(evadeMod);
		}
	}

	public virtual void DashFinished()
	{
		parent.dashTrails.SetActive(value: false);
		parent.TogglePreventFallCollider(status: true);
		parent.airborneStat.RemoveMod(airborneMod);
		parent.ToggleEnemyFloorCollisions();
		parent.movement.EndMovement();
	}

	public virtual void ExitTransition()
	{
		fsm.ChangeState(SlideState.staticID);
	}
}

